/* ==========================================================================
   VARIANT E · GRID — "corporate / modern"              (page-level Custom CSS)
   Paste into Pages → Variant E Grid → page settings → Custom CSS.
   INDY prefixes every rule with .page-variant-e-grid-<id>; nothing leaks.

   A product, not a venue: 12-column grid, uniform cards, one filled button
   per view, Jost only, 8px rhythm, hairlines instead of shadows.

   COLOURS
   1 BASE TOKENS read Theme & Style (--q-*). This persona reads Dark as the
     ground and Background as the text colour, on purpose.
   2 DEMO PALETTE is a test-site override. Delete on a customer site.
   3 DERIVED TOKENS are computed. Do not edit.
   ========================================================================== */

/* 1 · BASE TOKENS — keyed to Theme & Style */
[class*="section-"] {
  --v-ground:  var(--q-dark);        /* page ground          ← Dark */
  --v-text:    var(--q-background);  /* text                 ← Background */
  --v-brand:   var(--q-primary);     /* the one filled button← Primary */
  --v-brand-2: var(--q-secondary);   /* highlight outline    ← Secondary */
  --v-ok:      var(--q-accent);      /* status dot: showing  ← Accent */
  --v-warn:    var(--q-warning);     /* status dot: few left ← Warning */
}

/* 2 · DEMO PALETTE — Adam Template Testing 2 only. Delete on a customer site. */
[class*="section-"] {
  --v-ground:  #0E0E11;
  --v-text:    #F5F0E6;
  --v-brand:   #BF9B45;
  --v-brand-2: #D4B36A;
  --v-ok:      #5C8A6B;
  --v-warn:    #C08A3E;
}

/* 3 · DERIVED TOKENS — computed, do not edit */
[class*="section-"] {
  --v-card:      color-mix(in oklab, var(--v-text) 5%, var(--v-ground));
  --v-input:     color-mix(in oklab, var(--v-text) 9%, var(--v-ground));
  --v-line:      color-mix(in oklab, var(--v-text) 12%, transparent);
  --v-line-soft: color-mix(in oklab, var(--v-text) 22%, transparent);
  --v-muted:     color-mix(in oklab, var(--v-text) 62%, var(--v-ground));
  --v-faint:     color-mix(in oklab, var(--v-text) 42%, var(--v-ground));
  --v-on-brand:  var(--v-ground);
  --v-ui:        "Jost", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --v-ease:      cubic-bezier(0.2, 0.7, 0.2, 1);
}

/* ---- shared ground ---- */
[class*="section-"] {
  background-color: var(--v-ground);
  color: var(--v-text);
  font-family: var(--v-ui);
  overflow-x: clip;
}
[class*="section-"] *,
[class*="section-"] *::before,
[class*="section-"] *::after {
  box-sizing: border-box;
}
[class*="section-"] :is(h1, h2, h3, h4, .text-h2, .text-h5, .title) {
  font-family: var(--v-ui) !important;
  font-weight: 500 !important;
  letter-spacing: 0 !important;
  line-height: 1.2;
  text-transform: none !important;
  color: var(--v-text);
}
/* the 1200 content column */
[class*="section-"] .gr-wrap {
  max-width: 1200px;
  margin: 0 auto;
}
/* buttons: brass fill is the only filled control; everything else outline */
[class*="section-"] .gr-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 18px;
  border: 1px solid var(--v-line-soft);
  border-radius: 2px;
  font-family: var(--v-ui);
  font-size: 14px;
  font-weight: 500;
  color: var(--v-text);
  text-decoration: none;
  transition: border-color 120ms var(--v-ease), background-color 120ms var(--v-ease);
}
[class*="section-"] .gr-btn:hover {
  border-color: var(--v-text);
}
[class*="section-"] .gr-btn--primary {
  background: var(--v-brand);
  border-color: var(--v-brand);
  color: var(--v-on-brand);
}
/* every widget's primary button gets the same treatment */
[class*="section-"] :is(a, button).q-btn.bg-primary {
  min-height: 44px !important;
  padding: 0 18px !important;
  background: var(--v-brand) !important;
  color: var(--v-on-brand) !important;
  border-radius: 2px !important;
  box-shadow: none !important;
  font-family: var(--v-ui) !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
}
[class*="section-"] :is(a, button).q-btn.bg-primary :is(.q-btn__content, span) {
  color: var(--v-on-brand) !important;
}
[class*="section-"] button.q-btn.q-btn--outline {
  min-height: 44px !important;
  border: 1px solid var(--v-line-soft) !important;
  border-radius: 2px !important;
  color: var(--v-text) !important;
  font-family: var(--v-ui) !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  text-transform: none !important;
}
[class*="section-"] button.q-btn.q-btn--outline :is(.q-btn__content, span) {
  color: var(--v-text) !important;
}

/* ==========================================================================
   HERO E · PRODUCT PANEL  (Generic Carousel)
   440px slide inside the 1200 column; an opaque card sits left with status
   line (Subtitle), title, and the brass button. Dots are bars bottom-right,
   arrows are 40px outline squares. The card never moves between slides.
   ========================================================================== */
[class*="section-hero-e---product-panel-"] {
  padding: 32px 32px 0;
}
[class*="section-hero-e---product-panel-"] [data-test-id="generic-carousel"] {
  max-width: 1200px;
  margin: 0 auto;
}
[class*="section-hero-e---product-panel-"] .swiper-slide .row.justify-center.position-relative {
  height: 440px !important;
  min-height: 0 !important;
  overflow: hidden;
  border: 1px solid var(--v-line);
  border-radius: 3px;
}
[class*="section-hero-e---product-panel-"] img.full-width {
  width: 100% !important;
  height: 440px !important;
  object-fit: cover;
}
[class*="section-hero-e---product-panel-"] .flex.absolute-bottom {
  inset: 0 auto 0 0 !important;
  width: auto;
  height: 100% !important;
  display: flex !important;
  align-items: center;
  padding: 24px !important;
  background: transparent !important;
}
[class*="section-hero-e---product-panel-"] .flex.absolute-bottom .container {
  max-width: none !important;
  margin: 0 !important;
  padding: 0 !important;
}
[class*="section-hero-e---product-panel-"] .col.message {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 400px;
  max-width: 100%;
  padding: 24px !important;
  background: var(--v-card) !important;
  border: 1px solid var(--v-line);
  border-radius: 3px;
  text-align: left !important;
}
/* Subtitle = the status line ("Now showing · PG-13 · 118 min"), with a dot */
[class*="section-hero-e---product-panel-"] .subtitle {
  order: -1;
  display: flex !important;
  align-items: center;
  gap: 8px;
  margin: 0 0 8px !important;
  font-family: var(--v-ui) !important;
  font-size: 14px !important;
  font-weight: 400 !important;
  color: var(--v-muted) !important;
  text-shadow: none !important;
}
[class*="section-hero-e---product-panel-"] .subtitle::before {
  content: "";
  flex: 0 0 8px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--v-ok);
}
[class*="section-hero-e---product-panel-"] .subtitle:empty {
  display: none !important;
}
[class*="section-hero-e---product-panel-"] .title {
  margin: 0 0 16px !important;
  font-size: 40px !important;
  line-height: 1.15 !important;
  color: var(--v-text) !important;
  text-shadow: none !important;
}
[class*="section-hero-e---product-panel-"] .swiper-pagination {
  left: auto !important;
  right: 24px !important;
  bottom: 16px !important;
  width: auto !important;
}
[class*="section-hero-e---product-panel-"] .swiper-pagination-bullet {
  width: 24px !important;
  height: 3px !important;
  margin: 0 3px !important;
  border-radius: 0 !important;
  background: color-mix(in oklab, var(--v-text) 35%, transparent) !important;
  opacity: 1 !important;
}
[class*="section-hero-e---product-panel-"] .swiper-pagination-bullet-active {
  background: var(--v-text) !important;
}
[class*="section-hero-e---product-panel-"] :is(.swiper-button-prev, .swiper-button-next) {
  width: 40px;
  height: 40px;
  margin-top: -20px;
  background: color-mix(in oklab, var(--v-ground) 60%, transparent);
  border: 1px solid var(--v-line-soft);
  border-radius: 2px;
  color: var(--v-text) !important;
  text-shadow: none !important;
}
[class*="section-hero-e---product-panel-"] :is(.swiper-button-prev, .swiper-button-next)::after {
  font-size: 14px;
}

/* ==========================================================================
   HERO E · QUICK SELECTOR  (Showtime Quick Selector widget)
   One row of selects and a brass search button, in a card under the hero.
   The widget's DOM was not inspected on this site: QA this section first.
   ========================================================================== */
[class*="section-hero-e---quick-selector-"] {
  padding: 16px 32px 48px;
}
[class*="section-hero-e---quick-selector-"] > * {
  max-width: 1200px;
  margin: 0 auto;
}
[class*="section-hero-e---quick-selector-"] :is(.q-card, form) {
  padding: 16px !important;
  background: var(--v-card) !important;
  border: 1px solid var(--v-line);
  border-radius: 3px !important;
  box-shadow: none !important;
}
[class*="section-hero-e---quick-selector-"] .row {
  align-items: center;
  gap: 12px;
}
[class*="section-hero-e---quick-selector-"] .q-field__control {
  min-height: 44px !important;
  background: var(--v-input) !important;
  border-radius: 2px !important;
  box-shadow: none !important;
  color: var(--v-text) !important;
}
[class*="section-hero-e---quick-selector-"] .q-field__control::before,
[class*="section-hero-e---quick-selector-"] .q-field__control::after {
  display: none !important;
}
[class*="section-hero-e---quick-selector-"] :is(.q-field__label, .q-field__native, .q-select__dropdown-icon, .q-icon, .q-field__input) {
  font-family: var(--v-ui) !important;
  color: var(--v-text) !important;
}
[class*="section-hero-e---quick-selector-"] .q-field__label {
  color: var(--v-muted) !important;
}
[class*="section-hero-e---quick-selector-"] .q-btn:not(.q-btn--outline):not(.q-btn--flat) {
  min-height: 44px !important;
  background: var(--v-brand) !important;
  color: var(--v-on-brand) !important;
  border-radius: 2px !important;
  box-shadow: none !important;
  font-family: var(--v-ui) !important;
  font-weight: 500 !important;
  text-transform: none !important;
}
[class*="section-hero-e---quick-selector-"] .q-btn:not(.q-btn--outline):not(.q-btn--flat) :is(.q-btn__content, span) {
  color: var(--v-on-brand) !important;
}

/* ==========================================================================
   NOW PLAYING E · SCHEDULE TABLE  (Showtimes widget, list)
   Uniform rows, 56px poster, title 20/500, times as outline chips.
   ========================================================================== */
[class*="section-now-playing-e---schedule-table-"] {
  padding: 48px 32px 64px;
}
[class*="section-now-playing-e---schedule-table-"] .heading.container {
  max-width: 1200px !important;
  padding: 0 !important;
}
[class*="section-now-playing-e---schedule-table-"] .heading .row.text-center {
  justify-content: flex-start !important;
  text-align: left !important;
}
[class*="section-now-playing-e---schedule-table-"] .text-primary {
  color: var(--v-text) !important;
}
[class*="section-now-playing-e---schedule-table-"] .text-h2 {
  font-size: 28px !important;
  text-align: left !important;
}
/* date filter as a segmented control */
[class*="section-now-playing-e---schedule-table-"] .date-selector-list {
  display: inline-flex !important;
  justify-content: flex-start !important;
  border: 1px solid var(--v-line-soft);
  border-radius: 2px;
  overflow: hidden;
}
[class*="section-now-playing-e---schedule-table-"] .date-btn {
  min-width: 72px !important;
  margin: 0 !important;
  background: transparent !important;
  border: 0 !important;
  border-right: 1px solid var(--v-line) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
[class*="section-now-playing-e---schedule-table-"] .date-btn:last-child {
  border-right: 0 !important;
}
[class*="section-now-playing-e---schedule-table-"] .date-btn * {
  font-family: var(--v-ui) !important;
  font-size: 13px !important;
  color: var(--v-muted) !important;
}
[class*="section-now-playing-e---schedule-table-"] .date-btn.active {
  background: var(--v-input) !important;
}
[class*="section-now-playing-e---schedule-table-"] .date-btn.active * {
  color: var(--v-text) !important;
}
[class*="section-now-playing-e---schedule-table-"] .date-btn i.material-icons,
[class*="section-now-playing-e---schedule-table-"] .date-btn .q-icon {
  font-family: "Material Icons" !important;
  font-weight: 400 !important;
  font-style: normal !important;
  letter-spacing: normal !important;
  text-transform: none !important;
}
/* rows */
[class*="section-now-playing-e---schedule-table-"] [data-test-id="showtimes-by-film"] {
  max-width: 1200px;
  margin: 16px auto 0;
  border-top: 1px solid var(--v-line);
}
[class*="section-now-playing-e---schedule-table-"] .movie-container {
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border-bottom: 1px solid var(--v-line) !important;
}
[class*="section-now-playing-e---schedule-table-"] .movie-container > .absolute-full {
  display: none !important;
}
[class*="section-now-playing-e---schedule-table-"] .movie-container > .row.container {
  flex-wrap: nowrap !important;
  align-items: center !important;
  gap: 24px;
  padding: 16px 0 !important;
}
[class*="section-now-playing-e---schedule-table-"] .movie-container > .row.container > a:first-child {
  flex: 0 0 56px !important;
  width: 56px !important;
  max-width: 56px !important;
}
[class*="section-now-playing-e---schedule-table-"] .movie-container .q-img {
  height: 80px !important;
  padding-bottom: 0 !important;
  border-radius: 2px !important;
}
[class*="section-now-playing-e---schedule-table-"] .movie-container .text-h5 {
  font-size: 20px !important;
  line-height: 1.2 !important;
  color: var(--v-text) !important;
}
[class*="section-now-playing-e---schedule-table-"] .movie-container :is(.text-body2, .text-caption, p) {
  font-family: var(--v-ui) !important;
  font-size: 14px !important;
  color: var(--v-muted) !important;
}
[class*="section-now-playing-e---schedule-table-"] .showings .q-btn {
  min-height: 36px !important;
  margin: 4px 8px 4px 0 !important;
  padding: 0 12px !important;
  background: transparent !important;
  border: 1px solid var(--v-line-soft) !important;
  border-radius: 2px !important;
  box-shadow: none !important;
  font-family: var(--v-ui) !important;
  font-size: 14px !important;
  color: var(--v-text) !important;
  transition: border-color 120ms var(--v-ease);
}
[class*="section-now-playing-e---schedule-table-"] .showings .q-btn:hover {
  border-color: var(--v-text) !important;
}
[class*="section-now-playing-e---schedule-table-"] .showings .q-btn :is(.q-btn__content, span) {
  color: var(--v-text) !important;
}
[class*="section-now-playing-e---schedule-table-"] .no-schedule-message {
  max-width: 1200px;
  margin: 16px auto !important;
  padding: 40px 24px !important;
  background: var(--v-card);
  border: 1px solid var(--v-line);
  border-radius: 3px;
}
[class*="section-now-playing-e---schedule-table-"] .no-schedule-message :is(.q-icon, .message) {
  color: var(--v-muted) !important;
  font-family: var(--v-ui) !important;
}

/* ==========================================================================
   EVENTS E · PACKAGES  (Rich Text, sections/04-events-e-packages.html)
   Three package cards, the middle one outlined and carrying the page's
   only brass button, then a <details> FAQ.
   ========================================================================== */
[class*="section-events-e---packages-"] {
  padding: 64px 32px;
}
[class*="section-events-e---packages-"] .gr-pack__intro {
  max-width: 640px;
  margin: 0 auto 40px;
  text-align: center;
}
[class*="section-events-e---packages-"] .gr-pack__intro h2 {
  margin: 0 0 8px;
  font-size: 40px;
}
[class*="section-events-e---packages-"] .gr-pack__intro p {
  margin: 0;
  font-size: 16px;
  color: var(--v-muted);
}
[class*="section-events-e---packages-"] .gr-pack__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  align-items: stretch;
}
[class*="section-events-e---packages-"] .gr-pack__card {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 24px;
  background: var(--v-card);
  border: 1px solid var(--v-line);
  border-radius: 3px;
}
[class*="section-events-e---packages-"] .gr-pack__card--best {
  border: 2px solid var(--v-brand-2);
}
[class*="section-events-e---packages-"] .gr-pack__badge {
  position: absolute;
  top: -12px;
  left: 24px;
  margin: 0;
  padding: 2px 10px;
  background: var(--v-brand-2);
  border-radius: 2px;
  font-size: 12px;
  font-weight: 500;
  color: var(--v-on-brand);
}
[class*="section-events-e---packages-"] .gr-pack__name {
  margin: 0 0 4px;
  font-size: 20px;
  font-weight: 500;
}
[class*="section-events-e---packages-"] .gr-pack__price {
  margin: 0 0 20px;
  font-size: 28px;
  font-weight: 500;
}
[class*="section-events-e---packages-"] .gr-pack__price span {
  font-size: 14px;
  font-weight: 400;
  color: var(--v-muted);
}
[class*="section-events-e---packages-"] .gr-pack__list {
  margin: 0 0 24px;
  padding: 0;
  list-style: none;
  flex: 1 1 auto;
}
[class*="section-events-e---packages-"] .gr-pack__list li {
  display: flex;
  gap: 10px;
  padding: 8px 0;
  border-top: 1px solid var(--v-line);
  font-size: 14px;
  line-height: 1.5;
}
[class*="section-events-e---packages-"] .gr-pack__list li::before {
  content: "✓";
  flex: 0 0 auto;
  color: var(--v-ok);
}
[class*="section-events-e---packages-"] .gr-faq {
  max-width: 760px;
  margin: 64px auto 0;
}
[class*="section-events-e---packages-"] .gr-faq h3 {
  margin: 0 0 8px;
  font-size: 20px;
}
[class*="section-events-e---packages-"] .gr-faq details {
  border-top: 1px solid var(--v-line);
}
[class*="section-events-e---packages-"] .gr-faq details:last-child {
  border-bottom: 1px solid var(--v-line);
}
[class*="section-events-e---packages-"] .gr-faq summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 14px 0;
  cursor: pointer;
  list-style: none;
  font-size: 16px;
  font-weight: 500;
}
[class*="section-events-e---packages-"] .gr-faq summary::-webkit-details-marker {
  display: none;
}
[class*="section-events-e---packages-"] .gr-faq summary::after {
  content: "+";
  font-size: 20px;
  color: var(--v-muted);
}
[class*="section-events-e---packages-"] .gr-faq details[open] summary::after {
  content: "–";
}
[class*="section-events-e---packages-"] .gr-faq details p {
  margin: 0 0 16px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--v-muted);
}

/* ==========================================================================
   FOOD E · CATALOGUE  (Concessions Menu, grid, 4-up)
   Sidebar list rail, 4:3 images on top of uniform cards, footer row with
   price left and the add control right. Reads as e-commerce.
   ========================================================================== */
[class*="section-food-e---catalogue-"] {
  padding: 48px 32px 64px;
}
[class*="section-food-e---catalogue-"] .container {
  max-width: 1200px !important;
  padding: 0 !important;
}
[class*="section-food-e---catalogue-"] .container .row {
  justify-content: flex-start !important;
}
[class*="section-food-e---catalogue-"] .container h2 {
  font-size: 28px !important;
  text-align: left !important;
  color: var(--v-text) !important;
}
[class*="section-food-e---catalogue-"] .text-body1 {
  max-width: 1200px !important;
  margin: 0 auto !important;
  padding: 0 !important;
  text-align: left !important;
  font-size: 14px !important;
  color: var(--v-muted) !important;
}
[class*="section-food-e---catalogue-"] .full-width.q-py-md.row {
  max-width: 1200px;
  margin: 0 auto;
  gap: 24px;
}
/* sidebar rail */
[class*="section-food-e---catalogue-"] .col-2 {
  flex: 0 0 216px !important;
  width: 216px !important;
  max-width: 216px !important;
  padding: 0 !important;
}
[class*="section-food-e---catalogue-"] .category-filter-column {
  position: sticky !important;
  top: 104px;
  height: auto !important;
}
[class*="section-food-e---catalogue-"] :is(.q-scrollarea__container, .q-scrollarea__content) {
  position: static !important;
  height: auto !important;
}
[class*="section-food-e---catalogue-"] :is(.q-scrollarea__bar, .q-scrollarea__thumb) {
  display: none !important;
}
[class*="section-food-e---catalogue-"] .category-filter-column .q-btn {
  width: 100% !important;
  min-height: 40px !important;
  padding: 0 12px !important;
  justify-content: flex-start;
  background: transparent !important;
  border-radius: 2px !important;
  font-family: var(--v-ui) !important;
  font-size: 14px !important;
  font-weight: 400 !important;
  text-transform: none !important;
  color: var(--v-muted) !important;
  transition: background-color 120ms var(--v-ease);
}
[class*="section-food-e---catalogue-"] .category-filter-column .q-btn :is(.q-btn__content, span) {
  color: var(--v-muted) !important;
  justify-content: flex-start !important;
}
